def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])

    # The objects are n-by-n patterns placed on a lattice with one blank
    # row/column between neighboring objects.
    n = 4 if h == 19 else 3
    stride = n + 1

    # Find a complete example object, avoiding any blocks containing the 3
    # divider. The object itself gives the recursively repeated layout.
    best = None
    best_count = -1
    for i in range(n):
        for j in range(n):
            r0, c0 = i * stride, j * stride
            block = [[grid[r0+r][c0+c] for c in range(n)] for r in range(n)]
            if any(v == 3 for row in block for v in row):
                continue
            count = sum(v == 2 for row in block for v in row)
            if count > best_count:
                best, best_count = block, count

    if best is None:
        return a

    # Remove the divider.
    for r in range(h):
        for c in range(w):
            if a[r][c] == 3:
                a[r][c] = 0

    # A tile is present wherever the example object's corresponding cell is
    # occupied. Copy the motif into any such missing tile.
    for i in range(n):
        for j in range(n):
            if best[i][j] != 2:
                continue
            r0, c0 = i * stride, j * stride
            if not any(a[r0+r][c0+c] == 2 for r in range(n) for c in range(n)):
                for r in range(n):
                    for c in range(n):
                        a[r0+r][c0+c] = best[r][c]

    # Mark each object's cell indexed by its position in the larger lattice.
    for i in range(n):
        for j in range(n):
            if best[i][j] == 2:
                r, c = i * stride + i, j * stride + j
                if r < h and c < w and a[r][c] == 2:
                    a[r][c] = 8

    return a
